/** Convert one SourceEdit into the NAPI transport shape. */
export function toNapiSourceEdit(value: SourceEdit): Napi.SourceEdit {
    if (value.kind === "setText") {
        return {
            kind: "setText",
            path: value.path,
            text: value.text,
        };
    }

    if (value.kind === "editText") {
        return {
            kind: "editText",
            path: value.path,
            edits: value.edits.map((item) => toNapiTextEdit(item)),
        };
    }

    if (value.kind === "setBytes") {
        return {
            kind: "setBytes",
            path: value.path,
            bytes: Array.from(value.bytes),
        };
    }

    if (value.kind === "remove") {
        return {
            kind: "remove",
            path: value.path,
        };
    }

    if (value.kind === "move") {
        return {
            kind: "move",
            from: value.from,
            to: value.to,
        };
    }

    throw new Error("unknown SourceEdit");
}

