export function fromNapiFileId(value: Napi.FileId): FileId {
    return {
        id: value.id,
    };
}

/** Convert one NAPI FileContentId into the public bridge shape. */
export function fromNapiFileContentId(value: Napi.FileContentId): FileContentId {
    return {
        id: value.id,
    };
}

/** Convert one NAPI FileContent into the public bridge shape. */
export function fromNapiFileContent(value: Napi.FileContent): FileContent {
    if (value.kind === "text") {
        const payload_textContent = value.textContent;
        if (payload_textContent == null) {
            throw new Error("textContent payload is missing");
        }

        return {
            kind: "text",
            content: payload_textContent,
        };
    }

    if (value.kind === "binary") {
        const payload_binaryContent = value.binaryContent;
        if (payload_binaryContent == null) {
            throw new Error("binaryContent payload is missing");
        }

        return {
            kind: "binary",
            content: Uint8Array.from(payload_binaryContent),
        };
    }

    throw new Error("unknown FileContent");
}

/** Convert one ModuleId into the NAPI transport shape. */
export function toNapiModuleId(value: ModuleId): Napi.ModuleId {
    return {
        package: toNapiPackageId(value.package),
        key: value.key,
    };
}

